package com.example.starter.planningscene.dto;

import jakarta.validation.constraints.NotNull;

/**
 * 位姿请求体，所有分量必须显式提供且为有限数。
 */
public record PoseDto(
        @NotNull Double x,
        @NotNull Double y,
        @NotNull Double z,
        @NotNull Double qx,
        @NotNull Double qy,
        @NotNull Double qz,
        @NotNull Double qw) {
}

package com.example.starter.planningscene.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 单个关节赋值；关节名必须存在于机器人模型，位置必须有限且落在关节范围内。
 */
public record JointValueDto(
        @NotBlank String name,
        @NotNull Double position) {
}

package com.example.starter.planningscene.dto;

import com.example.starter.planningscene.domain.ObjectOperationType;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 批处理中的单个对象操作。不同类型按需取字段：
 * ADD 需要 frameId 或 linkId 二选一；UPDATE 可改几何/位姿/坐标系；
 * RENAME 需要 newId；ATTACH 需要 linkId；DETACH 需要 frameId。
 */
public record ObjectOperationDto(
        @NotNull ObjectOperationType type,
        String objectId,
        String newId,
        String frameId,
        String linkId,
        String geometry,
        PoseDto pose,
        List<String> touchLinks) {
}

package com.example.starter.planningscene.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Planning Scene 批量提交请求：一个请求内可同时更新关节、机器人姿态并执行多个对象操作。
 *
